"""Saved local weather-only demonstration; coding-assistant-authored program."""
w = df.copy()
w['date'] = pd.to_datetime(w['local_date'], format='%Y-%m-%d')
w = w.sort_values('date').reset_index(drop=True)
assert w['date'].is_unique
expected = pd.date_range('2024-01-01', '2024-12-31', freq='D')
assert w['date'].tolist() == expected.tolist()
assert w['station_id'].eq(240).all()
assert w['observed_hours'].eq(w['expected_hours']).all()
assert w['rain_missing_hours'].eq(0).all()
assert w['rain_mm'].notna().all() and w['rain_mm'].ge(0).all()
assert int(w['observed_hours'].sum()) == 8784
w['wet'] = w['rain_mm'].ge(1)
w['trace_scenario_wet'] = (w['rain_mm'] + .025 * w['rain_trace_hours']).ge(1)
monthly = w.groupby('month').agg(observed_days=('rain_mm','size'), precipitation_mm=('rain_mm','sum'), wet_days=('wet','sum')).reset_index()
monthly['wet_day_share_percent'] = 100 * monthly['wet_days'] / monthly['observed_days']
monthly['missing_days'] = [int((expected.month == month).sum()) - int(n) for month,n in zip(monthly['month'],monthly['observed_days'])]
assert int(monthly['wet_days'].sum()) == int(w['wet'].sum())
metric('Observed local days', len(w))
metric('Missing local days', len(expected.difference(w['date'])))
metric('Precipitation, mm · traces counted as zero', round(float(w['rain_mm'].sum()), 1))
metric('Wet days ≥1 mm / observed days', f"{int(w['wet'].sum())} / {len(w)} ({w['wet'].mean()*100:.2f}%)")
table('Monthly rainfall · denominators and missingness', monthly.round(3))
table('Weather summary and trace sensitivity', pd.DataFrame([{'observed_days':len(w),'missing_days':0,'total_mm':round(float(w['rain_mm'].sum()),1),'mean_mm_per_day':float(w['rain_mm'].mean()),'median_mm_per_day':float(w['rain_mm'].median()),'max_daily_mm':float(w['rain_mm'].max()),'wet_days_ge_1mm':int(w['wet'].sum()),'trace_hours':int(w['rain_trace_hours'].sum()),'trace_omission_upper_bound_mm_exclusive':float(w['trace_max_additional_mm'].sum()),'wet_days_trace_midpoint_scenario':int(w['trace_scenario_wet'].sum())}]).round(4))
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False,'svg.fonttype':'none'})
fig, ax = plt.subplots(figsize=(11,5.4))
ax.bar(w['date'],w['rain_mm'],width=1,color='#3c7181')
ax.axhline(1,color='#bd773c',linewidth=1,linestyle='--',label='Wet-day threshold: 1 mm')
ax.set(title='Schiphol rainfall across 2024',ylabel='Daily precipitation (mm)',xlabel='Europe/Amsterdam local date')
ax.legend(frameon=False); ax.grid(axis='y',alpha=.18); ax.set_axisbelow(True)
fig.subplots_adjust(bottom=.24,left=.09,right=.98,top=.88)
fig.text(.09,.055,'KNMI station 240 · 366 complete local days · traces counted as zero\nSchiphol is a regional proxy. These measurements do not describe cycling activity or trip exposure.',fontsize=9)
plot('Rainfall over time · Schiphol 2024',fig)
fig, ax = plt.subplots(figsize=(11,5.4))
bars=ax.bar(monthly['month'],monthly['wet_day_share_percent'],color='#3c7181')
ax.bar_label(bars,labels=[f'{n}/{d}' for n,d in zip(monthly['wet_days'],monthly['observed_days'])],padding=4,fontsize=10)
ax.set_xticks(range(1,13),['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])
ax.set(ylabel='Share of observed days with ≥1 mm (%)',ylim=(0,100),title='How often did a day cross 1 mm?')
ax.grid(axis='y',alpha=.18); ax.set_axisbelow(True)
fig.subplots_adjust(bottom=.24,left=.09,right=.98,top=.88)
fig.text(.09,.05,'Labels = wet days / observed days. Every local day in 2024 is observed; no missing day is counted as dry.\n“Below 1 mm” includes trace and light precipitation. This is an observed year, not a forecast.',fontsize=9)
plot('Monthly wet-day shares · explicit denominators',fig)
conclusion(f"Schiphol recorded {w['rain_mm'].sum():.1f} mm of precipitation across {len(w)} complete local days in 2024, with {int(w['wet'].sum())} days at or above 1 mm ({w['wet'].mean()*100:.2f}%). Missing days: 0. The median was {w['rain_mm'].median():.2f} mm/day. This describes recorded weather near Amsterdam, not cycling demand or behavior. The original cycling question remains unanswered because compatible bicycle counts were not obtained. KNMI trace hours are counted as zero; assigning an illustrative 0.025 mm per trace hour changes the wet-day count to {int(w['trace_scenario_wet'].sum())}. That sensitivity assumption is not a new observation. No future forecast or route-specific exposure claim follows.")
